#define IO_EXP_EN_PIN 5
#define IO_EXP_EN_PORT gpioPortF

/* I2C addresses (ADDR pin low/high) */
#define TCA6408A_ADDRESS_ADDR_LOW  0x20  /* ADDR = GND */
#define TCA6408A_ADDRESS_ADDR_HIGH 0x21  /* ADDR = VCC */
#define TCA6408A_DEFAULT_ADDRESS   TCA6408A_ADDRESS_ADDR_LOW

/* Register map (one 8-bit bank) */
#define TCA6408A_RA_INPUT      0x00
#define TCA6408A_RA_OUTPUT     0x01
#define TCA6408A_RA_POLARITY   0x02
#define TCA6408A_RA_CONFIG     0x03

/* Logical helpers */
#define TCA6408A_LOW  0
#define TCA6408A_HIGH 1

#define TCA6408A_POLARITY_NORMAL   0
#define TCA6408A_POLARITY_INVERTED 1

#define TCA6408A_OUTPUT 0
#define TCA6408A_INPUT  1

/* Pin defines P0..P7 */
#define TCA6408A_P0  0
#define TCA6408A_P1  1
#define TCA6408A_P2  2
#define TCA6408A_P3  3
#define TCA6408A_P4  4
#define TCA6408A_P5  5
#define TCA6408A_P6  6
#define TCA6408A_P7  7

